import { Dispatch, ReactNode, SetStateAction } from 'react';
import { Pressable, StyleSheet } from 'react-native';

type PopupProps = {
    children: ReactNode;
    controller: [
        boolean,
        Dispatch<SetStateAction<boolean>>
    ];
}

export default function Popup(props: PopupProps) {
    const [visible, setVisible] = props.controller;

    return (
        <Pressable style={[styles.overlay, visible ? {} : {display: 'none'}]} onPress={(e) => {
            e.stopPropagation();
            setVisible(false);
        }}>
            {props.children}
        </Pressable>
    );
}



const styles = StyleSheet.create({
    overlay: {
        flex: 1,
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: 'rgba(0, 0, 0, 0.5)',
        justifyContent: 'center',
        alignItems: 'center',
        width: '100%',
        height: '100%',
    },
});
